def is_polite(x):
    if x < 1:
        return False
    for k in range(1, int((x + 1) ** 0.5) + 1):
        if (k * (k + 1)) // 2 >= x:
            break
        if x % k == 0 and (x // k - k + 1) % 2 == 0:
            return True
    return False

def nth_polite_number(n):
    if n == 1:
        return 7
    k = 1
    while True:
        polite = (k * (k + 1)) // 2
        if polite >= n:
            return polite
        k += 1

